-- Der Handschalter heisst jetzt "abgegolten" (Entscheid Christoph 09.09.2026)
-- Keine Daten werden geaendert - nur die Beschriftung in der App.
INSERT INTO public.neuerungen (titel, text) VALUES
  ('Regiebericht: "Nicht verrechnen (abgegolten)"',
   'Der Knopf hiess bisher "Als verrechnet markieren" - dadurch stand ein Bericht als verrechnet da, ohne dass es je eine Rechnung gab. Er heisst jetzt "Nicht verrechnen (abgegolten)", fragt vorher nach und ist fuer Stunden gedacht, die in einer Pauschale stecken oder aus Kulanz nicht verrechnet werden. In der Liste steht dann "Abgegolten" statt "Verrechnet", und "Rechnung erstellen" bleibt jederzeit erreichbar.');
